    def _validate_value(self, dotpath: str, value: Any) -> Optional[str]:
        defn = self._schema.get(dotpath)
        if defn is None:
            return f"Unknown parameter: {dotpath}"

        if defn.type == "bool":
            if type(value) is not bool:
                return f"{dotpath}: expected bool, got {type(value).__name__}"
        elif defn.type == "int":
            if type(value) is not int:
                return f"{dotpath}: expected int, got {type(value).__name__}"
        elif defn.type == "float":
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                return f"{dotpath}: expected float, got {type(value).__name__}"
        elif defn.type in ("string", "enum"):
            if type(value) is not str:
                return f"{dotpath}: expected string, got {type(value).__name__}"
            if defn.allowed_values is not None and value not in defn.allowed_values:
                return f"{dotpath}: got {value!r}, allowed {defn.allowed_values}"

        return None

